77				upstream: "https://alice:s3:cr3t@api:internal:8080/base",
78				want:     []string{"route 1", `"api"`, "upstream", "more than one colon", `"https://***@api:internal:8080/base"`},
79				hidden:   []string{"alice", "s3:cr3t"},
80			},
