153		if want := "https://alice:s3cr%40t@host.internal:8443/v1/x"; res.UpstreamURL != want {
154			t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, want)
155		}
156		if cfg.Routes[0].Upstream != "https://alice:s3cr%40t@host.internal:8443/v1" {
157			t.Errorf("stored upstream = %q, want the original address with userinfo", cfg.Routes[0].Upstream)
158		}
