	hit := assertResolveSuccess(t, res)
	if hit.RouteID != "api" {
		t.Errorf("routeId = %q, want api", hit.RouteID)
	}
	if want := "https://alice:s3cr%40t@host.internal:8443/v1/items"; hit.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", hit.UpstreamURL, want)
	}
}

