package contractsentinel

import (
	"strings"
	"testing"
)

// This file pins, as regression coverage, which error ParseConfig selects and
// where it points when several errors coexist in one configuration document.
// The rules under test are the existing accept/reject rules; the precedence
// they rely on is layered in Config.UnmarshalJSON:
//
//  1. JSON syntax (a broken document is only ever a parse failure),
//  2. the routes element type and the id/methods/pathPrefix/upstream field
//     types (type errors),
//  3. queryTransforms array and rule validity (rule errors),
//  4. field contents such as a non-absolute pathPrefix, a bad method token or
//     an empty id (content errors, in Config.validate).
//
// Within one layer the earliest array position wins: routes by their position
// in the routes array and rules by their position in the route's
// queryTransforms array, never by id ordering. Every failure must hand back no
// config at all, so no half-parsed configuration can ever resolve a request.

// expectInvalidConfig parses src and requires an invalid_config Failure whose
// reason contains every want substring and none of the forbidden substrings,
// and requires ParseConfig to hand back no config. It returns the Failure for
// any extra, test-specific assertions.
func expectInvalidConfig(t *testing.T, src string, want, forbidden []string) *Failure {
	t.Helper()
	cfg, f := ParseConfig([]byte(src))
	if f == nil {
		t.Fatalf("expected invalid_config, config was accepted: %s", src)
	}
	if f.Code != "invalid_config" {
		t.Fatalf("code = %q, want invalid_config", f.Code)
	}
	if cfg != nil {
		t.Fatalf("a rejected config must not be returned (no half config to resolve with), got %+v", cfg)
	}
	for _, sub := range want {
		if !strings.Contains(f.Reason, sub) {
			t.Fatalf("reason = %q, want substring %q\nconfig: %s", f.Reason, sub, src)
		}
	}
	for _, sub := range forbidden {
		if strings.Contains(f.Reason, sub) {
			t.Fatalf("reason = %q must not contain %q\nconfig: %s", f.Reason, sub, src)
		}
	}
	return f
}

// TestFieldTypeErrorsBeatRuleErrors is the headline precedence: in a
// syntactically complete document, a route-element or basic-field TYPE error
// is reported before ANY queryTransforms rule error — even when the rule error
// sits on an earlier route. The reported reason targets the offending route's
// field, carries that route's valid non-empty id wherever the id appears in
// the object, and is independent of the object's field order. The document is
// legal JSON, so it must never be described as a parse failure.

package contractsentinel

import (
	"encoding/json"
	"strings"
	"testing"
)

func mustConfig(t *testing.T, src string) *Config {
	t.Helper()
	cfg, f := ParseConfig([]byte(src))
	if f != nil {
		t.Fatalf("unexpected config failure: %+v", f)
	}
	return cfg
}

func resolveJSON(t *testing.T, cfg *Config, reqSrc string) *Resolution {
	t.Helper()
	req, f := ParseRequest([]byte(reqSrc))
	if f != nil {
		t.Fatalf("unexpected request failure: %+v", f)
	}
	res, rf := Resolve(cfg, req)
	if rf != nil {
		t.Fatalf("unexpected resolve failure: %+v", rf)
	}
	return res
}

const sampleConfig = `{
  "routes": [
    {"id": "api",    "methods": ["GET"],        "pathPrefix": "/api",         "upstream": "http://api.internal/v1"},
    {"id": "api-v2", "methods": ["*"],          "pathPrefix": "/api/v2",      "upstream": "https://api.internal:8443/v2"},
    {"id": "orders", "methods": ["GET", "POST"],"pathPrefix": "/api/orders", "upstream": "http://orders.internal"},
    {"id": "root",   "methods": ["*"],          "pathPrefix": "/",            "upstream": "https://fallback.internal/base/"},
    {"id": "users",  "methods": ["GET"],        "pathPrefix": "/users",       "upstream": "http://users.internal/u"}
  ]
}`

func TestResolveBasicMatchAndJoin(t *testing.T) {
	cfg := mustConfig(t, sampleConfig)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "exact prefix strips and joins base path",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "api",
			upstream: "http://api.internal/v1/",
		},
		{
			name:     "prefix with deeper path joins on one slash",
			request:  `{"method":"GET","target":"/api/orders/42"}`,
			routeID:  "orders",
			upstream: "http://orders.internal/42",

package main

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

// These tests pin conflict adjudication at the command boundary after a
// save: the config is parsed through the public entry point, written with
// the standard library's encoding/json (the supported save path) and read
// back, and the real `resolve` command is then run offline against both the
// original and the saved config files. Exit status, stdout and stderr must
// match byte for byte in their observable JSON content, so a save cannot
// turn a conflict into a success, change the error code or move candidates.

// saveConfigJSON parses a config document through the public reader and
// writes it back with encoding/json, failing the test if the saved document
// would not re-read as a legal config.
func saveConfigJSON(t *testing.T, src string) string {
	t.Helper()
	cfg, f := contractsentinel.ParseConfig([]byte(src))
	if f != nil {
		t.Fatalf("parse original config: %v", f)
	}
	out, err := json.Marshal(cfg)
	if err != nil {
		t.Fatalf("marshal config: %v", err)
	}
	if _, f := contractsentinel.ParseConfig(out); f != nil {
		t.Fatalf("saved config rejected on re-read: %v\n%s", f, out)
	}
	return string(out)
}

// assertCLISameResult runs resolve against the original and the saved
// config and requires identical observable behavior: exit status, the full
// stdout (routeId/upstreamURL on success) and the full stderr JSON
// (code/reason/candidates on failure).
func assertCLISameResult(t *testing.T, original, saved, request string) resolveResult {
	t.Helper()
	before := runResolveCLI(t, original, request)
	after := runResolveCLI(t, saved, request)
	if before.exitCode != after.exitCode {
		t.Fatalf("exit status changed across save for %s: %d vs %d\n before stderr: %s\n after stderr:  %s",
			request, before.exitCode, after.exitCode, before.stderr, after.stderr)
	}
	if string(before.stdout) != string(after.stdout) {

// Command saveconfig demonstrates the offline save path of the resolve
// configuration: read a config through the fully validating entry point,
// save it back to JSON, read the saved document again, and resolve the same
// request before and after the save. It runs entirely offline and only uses
// the library's public entry points.
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

// configJSON carries a query-rewrite chain: rename every "old" parameter to
// "new", then set the (now merged) "new" parameter to the empty string.
const configJSON = `{
  "routes": [
    {
      "id": "api",
      "methods": ["GET"],
      "pathPrefix": "/api",
      "upstream": "http://api.internal/v1",
      "queryTransforms": [
        {"op": "rename", "name": "old", "to": "new"},
        {"op": "set", "name": "new", "value": ""}
      ]
    }
  ]
}`

// requestJSON carries duplicate parameters, an empty value, a raw percent
// escape and a parameter without '='.
const requestJSON = `{"method":"GET","target":"/api/orders/7?old=1&old=&keep=%2f%41&flag"}`

func main() {
	// 1. Read the configuration through the fully validating entry point.
	//    ParseConfig runs every check layer; when it returns a Failure there
	//    is no usable config at all, and the document must not be used.
	cfg, f := contractsentinel.ParseConfig([]byte(configJSON))
	if f != nil {
		fatal(f)
	}

	// 2. Save the validated config as JSON. encoding/json drives the
	//    library's MarshalJSON methods, so routes, methods, prefixes,
	//    upstreams and the rewrite rules (order and literal strings) are
	//    preserved; indentation and JSON string escaping may differ from
	//    the original file.
	saved, err := json.Marshal(cfg)
	if err != nil {
		fatal(&contractsentinel.Failure{Code: "internal_error", Reason: err.Error()})
	}
	fmt.Printf("saved config: %s\n", saved)

	// 3. Re-read the saved document through the same entry point. A
	//    successful save is not proof the document is a legal config — only
	//    ParseConfig decides that — so the re-read is validated again, and a
	//    failure here stops the saved config from being used.
	reloaded, f := contractsentinel.ParseConfig(saved)
	if f != nil {
		fatal(f)
	}

	// 4. Resolve the same request against the config from before and after
	//    the save. Both sides must select the same route and produce the
	//    same upstreamURL.
	req, f := contractsentinel.ParseRequest([]byte(requestJSON))
	if f != nil {
		fatal(f)
	}
	for _, step := range []struct {
		label string
		cfg   *contractsentinel.Config
	}{
		{"before save", cfg},
		{"after save ", reloaded},
	} {
		res, f := contractsentinel.Resolve(step.cfg, req)
		if f != nil {
			fatal(f)
		}
		fmt.Printf("%s: routeId=%s upstreamURL=%s\n", step.label, res.RouteID, res.UpstreamURL)
	}

	// 5. An empty route list saves as "routes": [] (never null, which the
	//    reader rejects as a type error), re-reads as a legal config and
	//    answers every legal request with route_not_found.
	empty, f := contractsentinel.ParseConfig([]byte(`{"routes": []}`))
	if f != nil {
		fatal(f)
	}
	savedEmpty, err := json.Marshal(empty)
	if err != nil {
		fatal(&contractsentinel.Failure{Code: "internal_error", Reason: err.Error()})
	}
	fmt.Printf("saved empty config: %s\n", savedEmpty)
	reloadedEmpty, f := contractsentinel.ParseConfig(savedEmpty)
	if f != nil {
		fatal(f)
	}
	if _, f := contractsentinel.Resolve(reloadedEmpty, req); f != nil {
		fmt.Printf("empty config resolve: code=%s reason=%s\n", f.Code, f.Reason)
	}
}

// fatal reports a failure the way the resolve command does — the stable
// code and the human-readable reason — and stops; a config or request that
// failed to read is never used.
func fatal(f *contractsentinel.Failure) {
	fmt.Fprintf(os.Stderr, "code=%s reason=%s\n", f.Code, f.Reason)
	os.Exit(1)
}

